1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export interface QuoteResult {
36	  premium: number;
37	}
38	
39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export interface ScenarioResult {
47	  results: StepResult[];
48	}
49	
50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	};
59	
60	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
61	
62	const quote = ({ items }: QuoteStep): QuoteResult => {
63	  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
64	
65	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
66	
67	  return {
68	    premium: Math.ceil(policyBase + firstInsuranceSurcharge + PROCESSING_FEE),
69	  };
70	};
71	
72	const runStep = (step: Step): StepResult => {
73	  if (step.op === "quote") return quote(step);
74	
75	  throw new Error(`unsupported step: ${step.op}`);
76	};
77	
78	export const runScenario = (scenario: Scenario): ScenarioResult => ({
79	  results: scenario.steps.map(runStep),
80	});
